import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
T="HTA EN URGENCIAS"; N=7
note=lambda t: f'<div style="font-size:34px;line-height:1.4;color:{G}">{t}</div>'
rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:20px">'+"".join(x)+'</div>'
def obj(k,meta,farm): return f'<div style="border-top:4px solid {K};padding-top:18px"><div style="font-size:36px;font-weight:800;letter-spacing:1px;color:{G}">{k}</div><div style="font-size:44px;font-weight:800;line-height:1.2;color:{R}">{meta}</div><div style="font-size:36px;font-weight:600;line-height:1.3">{farm}</div></div>'
def obj2(k,meta,farm): return f'<div style="border-top:4px solid {K};padding-top:14px"><div style="font-size:30px;font-weight:800;letter-spacing:1px;color:{G}">{k}</div><div style="font-size:38px;font-weight:800;line-height:1.2;color:{R}">{meta}</div><div style="font-size:31px;font-weight:600;line-height:1.3">{farm}</div></div>'
redline=lambda t: f'<div style="border-top:4px solid {K};padding-top:22px;font-size:42px;font-weight:800;line-height:1.3;color:{R}">{t}</div>'
P=[
page(1,N,T,big("¿200/110?",230,nowrap=True)+big(f'<span style="color:{R}">NO CORRAS</span>',170,nowrap=True)+'<div style="font-size:42px;font-weight:600;line-height:1.3;max-width:860px">Antes de tratar la cifra, busca el daño. Qué hacer, qué evitar y el objetivo en cada emergencia. Con ficha final.</div>',cover=True),
page(2,N,T,kicker("PRIMERA PREGUNTA")+big("¿HAY DAÑO AGUDO?",122,nowrap=True)+rows(line("Cerebro: focalidad, confusión, convulsiones"),line("Corazón: dolor torácico, edema de pulmón"),line("Aorta: dolor torácico o dorsal desgarrador"),line("Riñón y ojo: fracaso renal agudo, hemorragias o papiledema"),line("Embarazo o puerperio: preeclampsia"))+note("PA ≥ 180/110 con daño agudo = emergencia. Sin daño = HTA grave (la antigua «urgencia hipertensiva»).")),
page(3,N,T,kicker("SIN DAÑO AGUDO")+big("NO ES UNA EMERGENCIA",100,R,True)+rows(line("Repite la medida en reposo y trata el dolor, la ansiedad o la retención urinaria",True),line("No pidas analítica ni ECG solo por la cifra"),line("Reinicia o ajusta el oral y alta con control en una semana"),redline("Evita: bajarla rápido, captopril o nifedipino sublingual, IV solo por la cifra, ingresar solo por la cifra"))+note("En asintomáticos con PA ≥ 180/110, menos del 1 % tiene un evento cardiovascular a los 6 meses. Lo que le protege es el seguimiento.")),
page(4,N,T,kicker("CON DAÑO · CORAZÓN Y AORTA")+big("OBJETIVO",200,nowrap=True)+rows(obj("SÍNDROME CORONARIO AGUDO","PAS &lt; 140 de inmediato","Nitroglicerina o labetalol"),obj("EDEMA AGUDO DE PULMÓN","PAS &lt; 140 de inmediato","Nitroglicerina + furosemida (alternativa: urapidilo)"),obj("DISECCIÓN AÓRTICA","PAS &lt; 120 y FC &lt; 60 de inmediato","Esmolol + nitroglicerina (alternativa: labetalol)"))),
page(5,N,T,kicker("CON DAÑO · CEREBRO Y OTRAS")+big("OBJETIVO",150,nowrap=True)+rows(obj2("ENCEFALOPATÍA HIPERTENSIVA","PAM −20–25 % de inmediato","Labetalol"),obj2("ICTUS ISQUÉMICO","Con reperfusión: &lt; 185/110 antes y &lt; 180/105 en 24 h","Sin reperfusión: solo si ≥ 220/120, −15 % en 24 h"),obj2("HEMORRAGIA CEREBRAL","PAS 140–160 en las primeras 6 h","No bajes más de 70 mmHg en la primera hora"),obj2("HTA MALIGNA","PAM −20–25 % en varias horas","Labetalol (alternativa: urapidilo)"),obj2("PREECLAMPSIA GRAVE O ECLAMPSIA","PAS &lt; 160 y PAD &lt; 105 de inmediato","Labetalol + sulfato de magnesio. Valorar finalizar la gestación"))+note("Ninguna emergencia se trata bajando la PA a la normalidad de golpe.")),
page(6,N,T,kicker("EN LA GUARDIA")+big("FÁRMACOS IV",180,R,True)+rows(row("Labetalol","50 mg en ≥ 1 min"),note("Repite cada 5 min si hace falta. Máximo 200 mg."),row("Urapidilo","25 mg en 20 s"),note("Si a los 5 min no basta, repite 25 mg."),row("Nitroglicerina","SCA y edema de pulmón"),row("Esmolol","Disección aórtica"))+note("Monitorización continua de PA y ECG.")),
page(7,N,T,ficha_body("HTA EN URGENCIAS","Adulto",[("PRIMERO","¿Daño agudo de órgano? Cerebro, corazón, aorta, riñón, ojo, embarazo"),("SIN DAÑO","Reposo y repetir. Tratar dolor o ansiedad. Ajustar el oral. Control en una semana",True),("EVITA","Bajar rápido. Captopril o nifedipino SL. IV solo por la cifra",True),("SCA · EAP","PAS &lt; 140 inmediata. Nitroglicerina"),("DISECCIÓN","PAS &lt; 120 y FC &lt; 60. Esmolol + nitroglicerina",True),("ICTUS","Reperfusión: &lt; 185/110 y &lt; 180/105. Sin ella: solo si ≥ 220/120"),("HIC","PAS 140–160 en 6 h"),("ENCEFALOP.","Encefalopatía o HTA maligna: PAM −20–25 %. Labetalol"),("PREECL.","PAS &lt; 160 y PAD &lt; 105. Labetalol + Mg",True)],"ESC 2024 y ESH 2023 (emergencias hipertensivas); ACEP 2025 (HTA asintomática en Urgencias); fichas técnicas AEMPS",size=110,fs=28),ficha="08"),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","hta")
